(self.EP_STORY={"book":"The Last Ember Post","source":"SCENES.json captions (teaser = first sentence, story = full caption)","chapters":[{"n":1,"title":"The Last Roost","teaser":"For thirty years, Corwin Vale and his dragon Cinder had carried the mail of Highcairn from peak to peak.","story":"For thirty years, Corwin Vale and his dragon Cinder had carried the mail of Highcairn from peak to peak. Tonight the Dragon Post would close forever, because the new glass relay towers could send a message in a heartbeat.","data":null,"thumb":null,"lines":null,"cut":{"art":"data/cut/ep_01.jpg","from":[0.487,0.5,1.04],"to":[0.521,0.479,1.2],"mood":"#a06a48"}},{"n":2,"title":"Final Delivery at Midnight","teaser":"A brass notice was nailed to the roost door: FINAL DELIVERY AT MIDNIGHT.","story":"A brass notice was nailed to the roost door: FINAL DELIVERY AT MIDNIGHT. Cinder read it, snorted a curl of sparks, and pretended not to care.","data":null,"thumb":null,"lines":null,"cut":{"art":"data/cut/ep_02.jpg","from":[0.405,0.5,1.04],"to":[0.658,0.526,1.2],"mood":"#cb8c30"}},{"n":3,"title":"The Sorting Room","teaser":"Down in the sorting room, young postmistress Isla Fenn swept the last pigeonholes clean.","story":"Down in the sorting room, young postmistress Isla Fenn swept the last pigeonholes clean. In the very back, behind forty years of dust, she found a letter no one had ever delivered.","data":null,"thumb":null,"lines":null,"cut":{"art":"data/cut/ep_03.jpg","from":[0.39,0.5,1.04],"to":[0.684,0.483,1.2],"mood":"#d68633"}},{"n":4,"title":"The Ember Seal","teaser":"Its wax seal still glowed ember-red, warm as a coal in her hands.","story":"Its wax seal still glowed ember-red, warm as a coal in her hands. It was addressed in faded ink: To the Keeper of the Glass Peak, beyond the Stormwall.","data":"data/scene_04.js","thumb":"data:image/png;base64,","lines":"data/scene_04_line.js","cut":{"art":"data/cut/ep_04.jpg","from":[0.501,0.5,1.04],"to":[0.499,0.497,1.2],"mood":"#b05a32"}},{"n":5,"title":"The Oldest Map","teaser":"No courier had ever flown past the Stormwall and come back.","story":"No courier had ever flown past the Stormwall and come back. Isla unrolled the oldest map in the office and found the Glass Peak marked with a single star.","data":null,"thumb":null,"lines":null,"cut":{"art":"data/cut/ep_05.jpg","from":[0.433,0.5,1.04],"to":[0.612,0.614,1.2],"mood":"#d49c48"}},{"n":6,"title":"One Last Route","teaser":"Corwin looked at the letter, then at Cinder.","story":"Corwin looked at the letter, then at Cinder. ‘Our last route,’ he said. ‘Let’s make it one worth flying.’","data":null,"thumb":null,"lines":null,"cut":{"art":"data/cut/ep_06.jpg","from":[0.476,0.5,1.04],"to":[0.54,0.557,1.2],"mood":"#a35527"}},{"n":7,"title":"A Clerk of This Office","teaser":"Isla was already buttoning her coat.","story":"Isla was already buttoning her coat. ‘The letter belongs to this office,’ she said, ‘so a clerk of this office goes with it.’","data":null,"thumb":null,"lines":null,"cut":{"art":"data/cut/ep_07.jpg","from":[0.494,0.5,1.04],"to":[0.511,0.566,1.2],"mood":"#995b2c"}},{"n":8,"title":"Takeoff from Highcairn","teaser":"Cinder leapt from the tower, and the lights of Highcairn fell away beneath them like scattered embers.","story":"Cinder leapt from the tower, and the lights of Highcairn fell away beneath them like scattered embers.","data":null,"thumb":null,"lines":null,"cut":{"art":"data/cut/ep_08.jpg","from":[0.546,0.5,1.04],"to":[0.424,0.404,1.2],"mood":"#c3673b"}},{"n":9,"title":"The Relay Towers","teaser":"They flew past the new relay towers, each one crowned with a humming blue crystal.","story":"They flew past the new relay towers, each one crowned with a humming blue crystal. Cinder gave the nearest one a long, unimpressed look.","data":null,"thumb":null,"lines":null,"cut":{"art":"data/cut/ep_09.jpg","from":[0.457,0.5,1.04],"to":[0.572,0.387,1.2],"mood":"#3b79b6"}},{"n":10,"title":"Sky Lanterns at Kettle Rock","teaser":"At the village of Kettle Rock, people sent paper sky-lanterns up to greet the last dragon post.","story":"At the village of Kettle Rock, people sent paper sky-lanterns up to greet the last dragon post. Children shouted their names so Cinder would remember them.","data":null,"thumb":null,"lines":null,"cut":{"art":"data/cut/ep_10.jpg","from":[0.529,0.5,1.04],"to":[0.451,0.496,1.2],"mood":"#9b6f41"}},{"n":11,"title":"An Old Friend","teaser":"At the landing, an old woman pressed a bundle of spiced bread into Corwin’s hands.","story":"At the landing, an old woman pressed a bundle of spiced bread into Corwin’s hands. He had carried her son’s letters home from the far coast, thirty winters ago.","data":null,"thumb":null,"lines":null,"cut":{"art":"data/cut/ep_11.jpg","from":[0.491,0.5,1.04],"to":[0.514,0.38,1.2],"mood":"#c37631"}},{"n":12,"title":"The Crystal Cavern","teaser":"Beyond Kettle Rock the mountains turned to ice.","story":"Beyond Kettle Rock the mountains turned to ice. They sheltered for the night in a cavern where crystals glowed like frozen moonlight.","data":null,"thumb":null,"lines":null,"cut":{"art":"data/cut/ep_12.jpg","from":[0.4,0.5,1.04],"to":[0.666,0.435,1.2],"mood":"#667088"}},{"n":13,"title":"The First Pact","teaser":"By the fire, Corwin told Isla how the first postmaster made a pact with the wild dragons: people would never hunt them, and dragons would carry word between the peaks.","story":"By the fire, Corwin told Isla how the first postmaster made a pact with the wild dragons: people would never hunt them, and dragons would carry word between the peaks. ‘Nobody remembers the pact now,’ he said.","data":null,"thumb":null,"lines":null,"cut":{"art":"data/cut/ep_13.jpg","from":[0.496,0.5,1.04],"to":[0.507,0.625,1.2],"mood":"#dca73a"}},{"n":14,"title":"The Stormwall","teaser":"At dawn they saw the Stormwall: a wall of cloud a mile high, crackling with violet lightning.","story":"At dawn they saw the Stormwall: a wall of cloud a mile high, crackling with violet lightning.","data":null,"thumb":null,"lines":null,"cut":{"art":"data/cut/ep_14.jpg","from":[0.487,0.5,1.04],"to":[0.522,0.408,1.2],"mood":"#996c90"}},{"n":15,"title":"Into the Storm","teaser":"Cinder folded his notched wing tight and dove into the storm.","story":"Cinder folded his notched wing tight and dove into the storm. Rain hammered the saddle lantern, but its flame held.","data":null,"thumb":null,"lines":null,"cut":{"art":"data/cut/ep_15.jpg","from":[0.436,0.5,1.04],"to":[0.607,0.394,1.2],"mood":"#8d689e"}},{"n":16,"title":"Cinder Roars","teaser":"A bolt split the sky beside them.","story":"A bolt split the sky beside them. Cinder roared back at it, and for one moment ember light blazed through every seam of his scales.","data":"data/scene_16.js","thumb":"data:image/png;base64,","lines":"data/scene_16_line.js","cut":{"art":"data/cut/ep_16.jpg","from":[0.527,0.5,1.04],"to":[0.456,0.523,1.2],"mood":"#ab5524"}},{"n":17,"title":"The Catch","teaser":"The wind tore the letter from Isla’s satchel.","story":"The wind tore the letter from Isla’s satchel. She unbuckled one strap, leaned out into the gale, and caught it by its glowing seal.","data":null,"thumb":null,"lines":null,"cut":{"art":"data/cut/ep_17.jpg","from":[0.549,0.5,1.04],"to":[0.418,0.451,1.2],"mood":"#d58759"}},{"n":18,"title":"The Glass Peak","teaser":"Then, suddenly, there was silence.","story":"Then, suddenly, there was silence. They burst out of the storm into a sky full of stars, and before them rose a mountain made of glass.","data":null,"thumb":null,"lines":null,"cut":{"art":"data/cut/ep_18.jpg","from":[0.513,0.5,1.04],"to":[0.478,0.457,1.2],"mood":"#ad5e4e"}},{"n":19,"title":"Carvings in the Glass","teaser":"Light moved inside the mountain like fish in deep water.","story":"Light moved inside the mountain like fish in deep water. Carved into the glass were dragons, hundreds of them, and people standing beside them.","data":null,"thumb":null,"lines":null,"cut":{"art":"data/cut/ep_19.jpg","from":[0.518,0.5,1.04],"to":[0.47,0.423,1.2],"mood":"#cebf9a"}},{"n":20,"title":"The Glass Ledge","teaser":"Cinder landed on a ledge of glass.","story":"Cinder landed on a ledge of glass. He was trembling, and it was not from the cold.","data":null,"thumb":null,"lines":null,"cut":{"art":"data/cut/ep_20.jpg","from":[0.494,0.5,1.04],"to":[0.511,0.501,1.2],"mood":"#6b5a5f"}},{"n":21,"title":"The Keeper Wakes","teaser":"Something vast uncoiled in the heart of the mountain.","story":"Something vast uncoiled in the heart of the mountain. A pearl-white dragon rose into the starlight, her crystal horns shining like prisms.","data":null,"thumb":null,"lines":null,"cut":{"art":"data/cut/ep_21.jpg","from":[0.513,0.5,1.04],"to":[0.478,0.391,1.2],"mood":"#374589"}},{"n":22,"title":"Forty Years Late","teaser":"Corwin stepped forward, bowed the way couriers do, and held up the letter.","story":"Corwin stepped forward, bowed the way couriers do, and held up the letter. ‘Dragon Post, for the Keeper of the Glass Peak,’ he said. ‘Forty years late. Our apologies.’","data":null,"thumb":null,"lines":null,"cut":{"art":"data/cut/ep_22.jpg","from":[0.5,0.5,1.04],"to":[0.5,0.55,1.2],"mood":"#9a8375"}},{"n":23,"title":"The Golden Pact","teaser":"Vesperine breathed on the seal, and it unfolded into a ribbon of golden light.","story":"Vesperine breathed on the seal, and it unfolded into a ribbon of golden light. It was the pact itself, signed by the first postmaster: as long as one letter still flies between dragons and people, the old roads stay open.","data":null,"thumb":null,"lines":null,"cut":{"art":"data/cut/ep_23.jpg","from":[0.484,0.5,1.04],"to":[0.527,0.518,1.2],"mood":"#e1b057"}},{"n":24,"title":"The Smallest Hatchling","teaser":"Vesperine looked at Cinder for a long time.","story":"Vesperine looked at Cinder for a long time. ‘I know you,’ she said softly. ‘You were the smallest hatchling ever to leave this mountain.’","data":"data/scene_24.js","thumb":"data:image/png;base64,","lines":"data/scene_24_line.js","cut":{"art":"data/cut/ep_24.jpg","from":[0.439,0.5,1.04],"to":[0.602,0.391,1.2],"mood":"#ac787e"}},{"n":25,"title":"Highcairn Goes Dark","teaser":"Far below, a single flare rose from the valleys.","story":"Far below, a single flare rose from the valleys. The storm had cracked every relay crystal, and Highcairn lay dark, snowbound and cut off.","data":null,"thumb":null,"lines":null,"cut":{"art":"data/cut/ep_25.jpg","from":[0.464,0.5,1.04],"to":[0.56,0.463,1.2],"mood":"#30629c"}},{"n":26,"title":"The Call","teaser":"Vesperine lifted her head and called.","story":"Vesperine lifted her head and called. From every cave in the Glass Peak, wild dragons woke and spread their wings.","data":null,"thumb":null,"lines":null,"cut":{"art":"data/cut/ep_26.jpg","from":[0.418,0.5,1.04],"to":[0.636,0.565,1.2],"mood":"#917875"}},{"n":27,"title":"A Hundred Dragons","teaser":"They flew home at the head of a hundred dragons, each carrying a lantern, a sack of letters or a crate of supplies for the snowbound villages.","story":"They flew home at the head of a hundred dragons, each carrying a lantern, a sack of letters or a crate of supplies for the snowbound villages.","data":null,"thumb":null,"lines":null,"cut":{"art":"data/cut/ep_27.jpg","from":[0.534,0.5,1.04],"to":[0.443,0.484,1.2],"mood":"#ac6232"}},{"n":28,"title":"Every Window Lit","teaser":"When the dragons landed, Highcairn lit every window.","story":"When the dragons landed, Highcairn lit every window. The Dragon Post didn’t close that night, or any night after.","data":null,"thumb":null,"lines":null,"cut":{"art":"data/cut/ep_28.jpg","from":[0.494,0.5,1.04],"to":[0.509,0.397,1.2],"mood":"#796352"}},{"n":29,"title":"The New Courier","teaser":"Come spring, Corwin pinned his brass courier badge on Isla’s coat, and a young wild dragon with sapphire scales chose her as its rider.","story":"Come spring, Corwin pinned his brass courier badge on Isla’s coat, and a young wild dragon with sapphire scales chose her as its rider.","data":null,"thumb":null,"lines":null,"cut":{"art":"data/cut/ep_29.jpg","from":[0.508,0.5,1.04],"to":[0.486,0.481,1.2],"mood":"#927667"}},{"n":30,"title":"The Last Route","teaser":"Corwin and Cinder still fly one route every autumn, over the Stormwall to the Glass Peak.","story":"Corwin and Cinder still fly one route every autumn, over the Stormwall to the Glass Peak. They carry a single letter with a seal that glows like an ember, addressed: To the Keeper of the Glass Peak, from her son.","data":null,"thumb":null,"lines":null,"cut":{"art":"data/cut/ep_30.jpg","from":[0.62,0.5,1.04],"to":[0.3,0.488,1.2],"mood":"#d97831"}},{"n":101,"title":"Ninja Kat: Dojo at Sunset","teaser":"Bonus page: Ninja Kat on the dojo steps at sunset.","story":"Ninja Kat waves hello on the dojo steps as the sun sets over the village, while Master Tanuki waits in the doorway.","data":"data/scene_101.js","thumb":"data:image/png;base64,","lines":null,"cut":null,"bonus":true,"free":true,"slug":"ninja-kat","label":"Bonus","nodepth":true}]});
